namespace DesktopBox {
public static class FileImagePreviewTests {
 static BitmapSource Image(int width,int height,byte blue,byte green,byte red){var pixels=new byte[width*height*4];for(int i=0;i<pixels.Length;i+=4){pixels[i]=blue;pixels[i+1]=green;pixels[i+2]=red;pixels[i+3]=255;}var image=BitmapSource.Create(width,height,96,96,PixelFormats.Bgra32,null,pixels,width*4);image.Freeze();return image;}
 static void Write(string path,BitmapSource image,bool jpeg=false){BitmapEncoder encoder=jpeg?(BitmapEncoder)new JpegBitmapEncoder():new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(image));using(var stream=File.Create(path))encoder.Save(stream);}
 public static void Run(FileShelf shelf,string fixture,Action<string,bool> check){string png=Path.Combine(fixture,"中文图片.PNG"),jpg=Path.Combine(fixture,"测试照片.jpg"),portrait=Path.Combine(fixture,"竖图.png"),broken=Path.Combine(fixture,"损坏图片.jpg");Write(png,Image(1200,600,20,90,210));Write(jpg,Image(400,200,30,140,230),true);Write(portrait,Image(320,640,70,150,40));File.WriteAllText(broken,"not an image");bool thumbnail;var decoded=(BitmapSource)FileImagePreview.Get(png,out thumbnail);check("图片PNG显示真实内容且缩略图尺寸有界保持比例",thumbnail&&decoded.PixelWidth==128&&decoded.PixelHeight==64&&decoded.IsFrozen);var center=new byte[4];new FormatConvertedBitmap(decoded,PixelFormats.Bgra32,null,0).CopyPixels(new Int32Rect(30,20,1,1),center,4,0);check("图片预览读取真实像素而非通用文件图标",center[0]==20&&center[1]==90&&center[2]==210);var photo=(BitmapSource)FileImagePreview.Get(jpg,out thumbnail);check("JPEG图片可以正常预览",thumbnail&&photo.PixelWidth<=128&&photo.PixelHeight<=128);var tall=(BitmapSource)FileImagePreview.Get(portrait,out thumbnail);check("竖图按长边缩略不会解码成超大内存图片",thumbnail&&tall.PixelWidth==64&&tall.PixelHeight==128);using(var exclusive=new FileStream(png,FileMode.Open,FileAccess.ReadWrite,FileShare.None))check("缩略图读取后不锁定原图片文件",exclusive.Length>0);Write(png,Image(1200,600,200,40,10));File.SetLastWriteTimeUtc(png,DateTime.UtcNow.AddSeconds(2));var changed=(BitmapSource)FileImagePreview.Get(png,out thumbnail);check("原图片更新后缩略图缓存会失效",thumbnail&&!Object.ReferenceEquals(decoded,changed));var fallback=FileImagePreview.Get(broken,out thumbnail);check("损坏图片回退文件图标且不阻塞面板",!thumbnail&&fallback!=null);shelf.Receive(new[]{png,jpg,portrait});shelf.UpdateLayout();check("文件窗口图片实际绑定缩略图并保留文件名",AppearanceProbe.Visuals<Image>(shelf).Count(image=>Object.Equals(image.Tag,"file-image-preview"))>=3&&AppearanceProbe.Visuals<TextBlock>(shelf).Any(text=>text.Text==Path.GetFileName(png)));var entry=shelf.Files.Data.Items.First(item=>item.Path==jpg);check("图片显示修复不改变拖出原文件路径",((string[])shelf.DragData(entry).GetData(DataFormats.FileDrop))[0]==jpg);shelf.FilesScroll.ScrollToBottom();shelf.UpdateLayout();var shot=new RenderTargetBitmap((int)shelf.ActualWidth,(int)shelf.ActualHeight,96,96,PixelFormats.Pbgra32);shot.Render(shelf);Write(Path.Combine(Program.OutDir,"文件窗口图片缩略图.png"),shot);foreach(string path in new[]{png,jpg,portrait})shelf.Remove(shelf.Files.Data.Items.First(item=>item.Path==path).Id);check("移除图片入口会释放缩略图缓存引用",FileImagePreview.CachedCount==0);File.WriteAllText(Path.Combine(Program.OutDir,"文件图片预览核对.json"),new JavaScriptSerializer().Serialize(new{time=DateTimeOffset.Now.ToString("o"),png=new{decoded.PixelWidth,decoded.PixelHeight},portrait=new{tall.PixelWidth,tall.PixelHeight},maxPixels=FileImagePreview.MaxPixels,cacheLimit=FileImagePreview.MaxCache,scope="Own generated PNG/JPEG fixtures decoded and bound to real WPF image elements; original-file write access and cache invalidation checked. No user image altered."}),System.Text.Encoding.UTF8);}
}
